    p=argparse.ArgumentParser(); p.add_argument('--data',default='/kaggle/input'); p.add_argument('--out',default='/kaggle/working/Atlas-v3.1-audit'); p.add_argument('--mode',choices=['proxy','smoke','full'],default='full'); args,_=p.parse_known_args(); main(args.data,args.out,args.mode)
